+use v5.42;
+
+# Example 1: Constant true condition - dead else branch
+method always_true() {
+    if (1) {
+        return 42;
+    }
+    return 0;  # Dead code - never reached
+}
+
+# Example 2: Constant false condition - dead then branch
+method always_false() {
+    if (0) {
+        return 42;  # Dead code - never reached
+    }
+    return 0;
+}
+
