   152→                print("$ARGV[0] syntax error\n") if @ARGV;
   153→                print("syntax error\n") unless @ARGV;
   154→            } else {
   155→                print("Parse failed\n");
   156→            }
   157→            exit 1;  # Failure - like perl -c
   158→        }
   159→    }
