#!/usr/bin/env perl
use 5.42.0;
use FindBin qw($RealBin);
use lib "$RealBin/lib";
use Chalk::Grammar::BNF;
use Chalk::Parser;
use Chalk::Preprocessor::Heredoc;
use File::Spec;

# Load grammar from BNF file
my $bnf_file = File::Spec->catfile($RealBin, "grammar", "chalk.bnf");
open my $grammar_fh, "<:utf8", $bnf_file or die "Cannot open $bnf_file: $!";
my $bnf_content = do { local $/; <$grammar_fh> };
close $grammar_fh;
my $chalk_grammar = Chalk::Grammar->build_from_bnf($bnf_content, "Program");

my $parser = Chalk::Parser->new(grammar => $chalk_grammar);

# Read Block.pm
my $file = "$RealBin/lib/Chalk/Grammar/Chalk/Rule/Block.pm";
open my $fh, '<', $file or die "Cannot read $file: $!";
my $source = do { local $/; <$fh> };
close $fh;

# Preprocess heredocs
my $preprocessor = Chalk::Preprocessor::Heredoc->new(input => $source);
$preprocessor->transform();
my $preprocessed = $preprocessor->output;

print "File length: " . length($preprocessed) . " bytes\n";
print "Attempting to parse...\n\n";

# Attempt to parse
my $result = $parser->parse_string($preprocessed);

if ($result) {
    print "SUCCESS: File parsed completely!\n";
} else {
    my $pos = $parser->position // 0;
    my $total = length($preprocessed);
    my $pct = sprintf("%.1f%%", ($pos / $total) * 100);

    print "PARSING_STOPPED at position $pos of $total ($pct)\n\n";

    # Show context around failure point
    my $start = $pos > 100 ? $pos - 100 : 0;
    my $end = $pos + 100 < $total ? $pos + 100 : $total;

    print "Context around failure:\n";
    print "-" x 60 . "\n";
    my $context = substr($preprocessed, $start, $end - $start);
    print $context;
    print "\n" . "-" x 60 . "\n";
    print "Failure point marked at position $pos\n";

    # Show the exact character where parsing stopped
    if ($pos < $total) {
        my $char = substr($preprocessed, $pos, 1);
        print "Character at failure: '$char' (ASCII " . ord($char) . ")\n";
    }
}

