     2→# ABOUTME: Handles while loop control flow with Loop nodes, lazy phis, and backedges
     3→
     4→use 5.42.0;
     5→use experimental 'class';
     6→use Scalar::Util qw(blessed);
     7→
     8→class Chalk::Grammar::Chalk::Rule::WhileStatement :isa(Chalk::GrammarRule) {
     9→    method evaluate($context) {
    10→        # WhileStatement -> 'while' WS_OPT '(' WS_OPT Expression WS_OPT ')' WS_OPT Block
    11→        # Actual children after parsing with semantic actions:
    12→        # Indices: 0       1     2   3        4     5     6
    13→        # child[3] is the Expression node, child[6] is the Block
    14→
    15→        my @children = $context->children->@*;
    16→        my $builder = $context->env->{ir_builder};
    17→        return undef unless $builder;
    18→
    19→        # Save entry control
    20→        my $entry_control = $builder->current_control;
    21→
    22→        # Create Loop node with entry control
    23→        my $loop = $builder->build_loop_node($entry_control);
    24→
    25→        # Set current control to Loop for condition evaluation
    26→        $builder->set_control($loop->id);
    27→
    28→        # Get condition expression (child 3)
    29→        my $condition = $context->child(3);
    30→        return undef unless (blessed($condition) && $condition->can('id'));
    31→
    32→        # Build If node for loop condition
    33→        my $if_node = $builder->build_if_node($condition);
    34→        my $if_true = $builder->build_if_true_node($if_node);
    35→        my $if_false = $builder->build_if_false_node($if_node);
    36→
    37→        # Get loop body Block (child 6)
    38→        my $body_block = $context->child(6);
    39→        return undef unless (ref($body_block) eq 'HASH' && $body_block->{type} eq 'block');
    40→
    41→        # NOTE: Assignment and VariableDeclaration now use placeholder control pattern
    42→        # Simple assignments like "$i = 5" work correctly in loops
    43→        # Complex assignments like "$i = $i - 1" work but may use incomplete parse
    44→        # (SPPF creates both parses, semiring currently picks incomplete one - needs optimization pass)
    45→
    46→        # Track variables modified in loop for phi node generation
    47→        # Save scope state before loop (for future phi node implementation)
    48→        # my $scope_before_loop = $builder->scope;
    49→
    50→        # Wire up body statements with IfTrue control
    51→        # Track break and continue exits
    52→        my @break_controls;
    53→        my @continue_controls;
    54→        my $current_ctrl = $if_true->id;
    55→
    56→        for my $stmt (@{$body_block->{statements}}) {
    57→            # Check if this is a break or continue metadata hash
    58→            if (ref($stmt) eq 'HASH') {
    59→                if ($stmt->{type} eq 'break') {
    60→                    push @break_controls, $current_ctrl;
    61→                    next;  # Don't advance control - this path exits loop
    62→                } elsif ($stmt->{type} eq 'continue') {
    63→                    push @continue_controls, $current_ctrl;
    64→                    next;  # Don't advance control - this path jumps to loop start
    65→                }
    66→            }
    67→
    68→            # Regular statement - wire control if needed
    69→            if (blessed($stmt) && $stmt->can('inputs')) {
    70→                if ($stmt->inputs->[0] eq '__CONTROL_PLACEHOLDER__') {
    71→                    $builder->set_node_control($stmt, $current_ctrl);
    72→                }
    73→                $current_ctrl = $stmt->id;  # Next statement uses this as control
    74→            }
    75→        }
    76→
    77→        # Build backedge: merge normal end-of-body + continue paths
    78→        my @backedge_controls = ($current_ctrl, @continue_controls);
    79→        if (@backedge_controls > 1) {
    80→            # Multiple paths back to loop - need Region
    81→            my $backedge_region = $builder->build_region_node(@backedge_controls);
    82→            push $loop->inputs->@*, $backedge_region->id;
    83→        } elsif (@backedge_controls == 1) {
    84→            # Single path back
    85→            push $loop->inputs->@*, $backedge_controls[0];
    86→        }
    87→        # If no backedge controls, loop has no normal exit (only break)
    88→
    89→        # Build exit region: merge IfFalse (normal exit) + break paths
    90→        my @exit_controls = ($if_false->id, @break_controls);
    91→        my $exit_region;
    92→        if (@exit_controls > 1) {
    93→            $exit_region = $builder->build_region_node(@exit_controls);
