    method build_constant_node($value, $type = 'Int') {
        my $attributes = { value => $value, type => $type };
        my $constant = Chalk::IR::Node->new(
            id => $self->next_node_id(),
            op => 'Constant',
            inputs => [$current_control],
            attributes => $attributes
        );
        $graph->add_node($constant);
        return $constant;
    }

