    }

    # Control flow nodes
    method build_if_node($condition_node) {
        my $condition_ref = { op => 'NodeRef', node_id => $condition_node->id };
        my $attributes = { condition => $condition_ref };
        my $if_node = Chalk::IR::Node->new(
