        my $attributes = {
            left => $left_ref,
            right => $right_ref
        };
        my $sub = Chalk::IR::Node->new(
            id => $self->next_node_id(),
            op => 'Sub',
            inputs => [$current_control, $left_node->id, $right_node->id],
            attributes => $attributes
        );
        $graph->add_node($sub);
        return $sub;
    }

