        return $region;
    }

    method build_phi_node($region_node, @value_inputs) {
        my $empty_attrs = {};
        my $phi = Chalk::IR::Node->new(
            id => $self->next_node_id(),
            op => 'Phi',
            inputs => [$region_node->id, @value_inputs],
