        my $right_ref = { op => 'NodeRef', node_id => $right_node->id };
        my $attributes = {
            left => $left_ref,
            right => $right_ref
        };
        my $cmp = Chalk::IR::Node->new(
            id => $self->next_node_id(),
            op => 'Equal',
            inputs => [$current_control, $left_node->id, $right_node->id],
            attributes => $attributes
