    my $loop = Chalk::IR::Node->new(
        id => 2,
        op => 'Loop',
        inputs => [$start->id],
        attributes => {},
    );
    $graph->add_node($loop);

    # Loop phi has initial value and placeholder for backedge
    my $phi = Chalk::IR::Node->new(
